#include <iostream>
using namespace std;

const int N = 100010;

int head;
int e[N], ne[N];
int idx;

void init() {
    head = -1;
    idx = 0;
}

void add_to_head(int x) {
    e[idx] = x;
    ne[idx] = head;
    head = idx;
    idx++;
}

void add_after(int k, int x) {
    e[idx] = x;
    ne[idx] = ne[k];
    ne[k] = idx;
    idx++;
}

void remove_after(int k) {
    ne[k] = ne[ne[k]];
}

int main() {
    int m;
    cin >> m;

    init();

    while (m--) {
        char op;
        cin >> op;

        if (op == 'H') {
            int x;
            cin >> x;
            add_to_head(x);
        } else if (op == 'I') {
            int k, x;
            cin >> k >> x;
            add_after(k - 1, x);
        } else if (op == 'D') {
            int k;
            cin >> k;

            if (k == 0) {
                head = ne[head];
            } else {
                remove_after(k - 1);
            }
        }
    }

    for (int i = head; i != -1; i = ne[i]) {
        cout << e[i] << ' ';
    }

    return 0;
}
